S=.claude/skills/short-drama-write/scripts; for ep in EP001 EP002 EP003; do T=$(python3 -c "from pathlib import Path; import tempfile, uuid; print(Path(tempfile.gettempdir()) / ('short-drama-' + uuid.uuid4().hex + '.jsonl'))"); echo "== $ep"; python3 $S/screenplay_index.py "剧集/$ep/剧本.md" --output "$T" --speaker 沈知微 --speaker 林晚棠 --speaker 顾承泽 --speaker 陆既明 --speaker 马金宝 --speaker 宾客甲 --speaker 宾客乙 --speaker 秦守义 --speaker 秦小满 --speaker 吴姨 2>&1 | tail -5; python3 -c "
import json,sys,collections
c=collections.Counter(); w=[]
for l in open('$T'):
  r=json.loads(l); c[r.get('block_type') or r.get('type')]+=1
  for k in ('warnings','warning','ambiguity','issues'):
    if r.get(k): w.append((r.get('block_id'),r.get(k)))
print(dict(c)); print(w[:10])
"; python3 $S/duration_estimate.py "剧集/$ep/剧本.md" --index "$T" 2>&1 | head -20; done

